function getDesc(name){
  if(!name)return null;
  if(DESC[name])return DESC[name];
  var base=name.replace(/\s*\([^)]*\)\s*$/,'').trim();
  if(base!==name&&DESC[base])return DESC[base];
  var aliases={'KB ':'Kettlebell ','DB ':'Dumbbell ','BB ':'Barbell ','BW ':'Bodyweight '};
  for(var k in aliases){if(name.startsWith(k)){var alt=aliases[k]+name.slice(k.length);if(DESC[alt])return DESC[alt];var altBase=alt.replace(/\s*\([^)]*\)\s*$/,'').trim();if(altBase!==alt&&DESC[altBase])return DESC[altBase];}}
  var stripped=name.replace(/\s+(max|heavy|light|slow|fast|deep|full|gentle|modified|easy|strict|max distance|max reps|max weight|max time|max hold)\s*$/i,'').trim();
  if(stripped!==name&&DESC[stripped])return DESC[stripped];
  var noHand=name.replace(/^(Two-Hand|One-Hand|Single-Arm|Double)\s+/i,'').trim();
  if(noHand!==name){if(DESC[noHand])return DESC[noHand];var kbVer='Kettlebell '+noHand;if(DESC[kbVer])return DESC[kbVer];}
  return null;
}
